import { expectStatus, test } from "../../fixtures";

test("A member cannot see another tenant's vendor audit trail", { tag: "@AUD-02" }, async ({ apiAs, factory }) => {
  // Arrange
  const member = await apiAs("member");
  const globex = await apiAs("otherTenant");
  const vendor = await factory.vendor({ as: "otherTenant" });
  // The trail exists for its own tenant, so a 404 below means it's hidden, not missing.
  await expectStatus(await globex.get(`/api/vendors/${vendor.id}/audit`), 200);

  // Act
  const response = await member.get(`/api/vendors/${vendor.id}/audit`);

  // Assert
  await expectStatus(response, 404);
});
